    loadTools()
    loadSyncRuns()
  }, [])

  const loadTools = async () => {
    const { data } = await supabase
      .schema('catalog').from('tools')
      .select('*')
      .order('name')
    if (data) setTools(data)
  }

  const loadSyncRuns = async () => {
    const { data } = await supabase
      .schema('catalog').from('sync_runs')
