import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Activity, Cpu, Server, Wifi } from 'lucide-react';

interface HealthData {
  status: 'healthy' | 'degraded' | 'down';
  uptime: number;
  cpu: number;
  memory: number;
  lastCheck: string;
  services: { name: string; status: string }[];
}

interface HealthCardProps {
  data: HealthData;
}

export function HealthCard({ data }: HealthCardProps) {
  const statusColor = {
    healthy: 'bg-green-500',
    degraded: 'bg-yellow-500',
    down: 'bg-red-500',
  }[data.status];

  const statusLabel = {
    healthy: 'Saudável',
    degraded: 'Degradado',
    down: 'Indisponível',
  }[data.status];

  return (
    <Card>
      <CardHeader className="flex flex-row items-center justify-between space-y-0 pb-2">
        <CardTitle className="text-sm font-medium">Saúde do Sistema</CardTitle>
        <Activity className="h-4 w-4 text-muted-foreground" />
      </CardHeader>
      <CardContent>
        <div className="flex items-center gap-2 mb-4">
          <div className={`h-3 w-3 rounded-full ${statusColor}`} />
          <span className="text-lg font-bold">{statusLabel}</span>
        </div>
        <div className="grid grid-cols-2 gap-4 text-sm">
          <div className="flex items-center gap-2">
            <Server className="h-4 w-4 text-muted-foreground" />
            <span>Uptime: {Math.floor(data.uptime / 3600)}h</span>
          </div>
          <div className="flex items-center gap-2">
            <Cpu className="h-4 w-4 text-muted-foreground" />
            <span>CPU: {data.cpu}%</span>
          </div>
          <div className="flex items-center gap-2">
            <Wifi className="h-4 w-4 text-muted-foreground" />
            <span>RAM: {data.memory}%</span>
          </div>
          <div className="flex items-center gap-2">
            <span className="text-xs text-muted-foreground">Último: {data.lastCheck}</span>
          </div>
        </div>
        <div className="mt-4 space-y-1">
          {data.services.map((svc) => (
            <div key={svc.name} className="flex items-center justify-between text-xs">
              <span>{svc.name}</span>
              <Badge variant={svc.status === 'healthy' ? 'default' : 'destructive'}>
                {svc.status}
              </Badge>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

import React from 'react';
import { AlertTriangle, X } from 'lucide-react';

interface Alert {
  id: string;
  type: 'critical' | 'warning' | 'info';
  message: string;
  timestamp: string;
}

interface AlertBannerProps {
  alerts: Alert[];
  onDismiss: (id: string) => void;
}

export function AlertBanner({ alerts, onDismiss }: AlertBannerProps) {
  if (!alerts || alerts.length === 0) return null;

  const visibleAlerts = alerts.slice(0, 3);

  return (
    <div className="space-y-2 mb-4">
      {visibleAlerts.map((alert) => {
        const bgColor =
          alert.type === 'critical'
            ? 'bg-red-900/50 border-red-500'
            : alert.type === 'warning'
            ? 'bg-yellow-900/50 border-yellow-500'
            : 'bg-blue-900/50 border-blue-500';

        return (
          <div
            key={alert.id}
            className={`flex items-start gap-3 p-3 rounded-lg border ${bgColor}`}
          >
            <AlertTriangle className="w-5 h-5 mt-0.5 flex-shrink-0 text-current" />
            <div className="flex-1 min-w-0">
              <p className="text-sm font-medium">{alert.message}</p>
              <p className="text-xs text-muted-foreground mt-1">
                {new Date(alert.timestamp).toLocaleString()}
              </p>
            </div>
            <button
              onClick={() => onDismiss(alert.id)}
              className="p-1 hover:bg-black/20 rounded transition-colors"
            >
              <X className="w-4 h-4" />
            </button>
          </div>
        );
      })}
    </div>
  );
}

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Clock, CheckCircle2, XCircle, AlertTriangle, Loader2 } from 'lucide-react';

interface TimelineEntry {
  id: string;
  event: string;
  status: 'success' | 'error' | 'warning' | 'pending';
  timestamp: string;
  details?: string;
}

interface StatusTimelineProps {
  entries: TimelineEntry[];
  loading?: boolean;
}

const statusIcon = (status: string) => {
  switch (status) {
    case 'success': return <CheckCircle2 className="h-4 w-4 text-green-500" />;
    case 'error': return <XCircle className="h-4 w-4 text-red-500" />;
    case 'warning': return <AlertTriangle className="h-4 w-4 text-yellow-500" />;
    case 'pending': return <Loader2 className="h-4 w-4 text-blue-500 animate-spin" />;
    default: return <Clock className="h-4 w-4 text-muted-foreground" />;
  }
};

const statusBadge = (status: string) => {
  const map: Record<string, { label: string; variant: 'default' | 'secondary' | 'destructive' | 'outline' }> = {
    success: { label: 'Sucesso', variant: 'default' },
    error: { label: 'Erro', variant: 'destructive' },
    warning: { label: 'Alerta', variant: 'secondary' },
    pending: { label: 'Pendente', variant: 'outline' },
  };
  const m = map[status] || { label: status, variant: 'outline' as const };
  return <Badge variant={m.variant}>{m.label}</Badge>;
};

export function StatusTimeline({ entries, loading }: StatusTimelineProps) {
  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Clock className="h-5 w-5" />
            Linha do Tempo
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center justify-center py-8 text-muted-foreground">
            <Loader2 className="h-5 w-5 animate-spin mr-2" />
            Carregando eventos...
          </div>
        </CardContent>
      </Card>
    );
  }

  if (!entries || entries.length === 0) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="text-lg flex items-center gap-2">
            <Clock className="h-5 w-5" />
            Linha do Tempo
          </CardTitle>
        </CardHeader>
        <CardContent>
          <p className="text-muted-foreground text-center py-8">Nenhum evento registrado.</p>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="text-lg flex items-center gap-2">
          <Clock className="h-5 w-5" />
          Linha do Tempo
        </CardTitle>
      </CardHeader>
      <CardContent>
        <div className="space-y-4">
          {entries.map((entry) => (
            <div key={entry.id} className="flex items-start gap-3 border-l-2 border-border pl-4 pb-4 last:pb-0">
              <div className="mt-0.5">{statusIcon(entry.status)}</div>
              <div className="flex-1 min-w-0">
                <div className="flex items-center gap-2 flex-wrap">
                  <span className="font-medium text-sm">{entry.event}</span>
                  {statusBadge(entry.status)}
                </div>
                {entry.details && (
                  <p className="text-xs text-muted-foreground mt-1">{entry.details}</p>
                )}
                <p className="text-xs text-muted-foreground mt-1">
                  {new Date(entry.timestamp).toLocaleString('pt-BR')}
                </p>
              </div>
            </div>
          ))}
        </div>
      </CardContent>
    </Card>
  );
}

import React, { useState, useEffect } from 'react';
import { ToolCard } from './ToolCard';
import { SyncButton } from './SyncButton';
import { Badge } from '@/shared/ui/badge';
import { Input } from '@/shared/ui/input';
import { Search, Filter } from 'lucide-react';

interface Tool {
  id: string;
  name: string;
  description: string;
  category: string;
  tags: string[];
  version: string;
  is_deprecated: boolean;
  health_status?: 'healthy' | 'degraded' | 'down' | 'unknown';
  last_health_check?: string;
}

interface SyncRun {
  id: string;
  status: string;
  started_at: string;
  finished_at: string;
  tools_found: number;
  tools_added: number;
  tools_updated: number;
}

export function CatalogTab() {
  const [tools, setTools] = useState<Tool[]>([]);
  const [syncRuns, setSyncRuns] = useState<SyncRun[]>([]);
  const [search, setSearch] = useState('');
  const [filterCategory, setFilterCategory] = useState<string>('all');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadTools();
    loadSyncRuns();
  }, []);

  async function loadTools() {
    try {
      const { hubClient } = await import('@/integrations/supabase/hub-client');
      const { data } = await hubClient.from('catalog_tools').select('*').order('name');
      if (data) setTools(data);
    } catch (err) {
      console.error('Erro ao carregar tools:', err);
    } finally {
      setLoading(false);
    }
  }

  async function loadSyncRuns() {
    try {
      const { hubClient } = await import('@/integrations/supabase/hub-client');
      const { data } = await hubClient.from('catalog_sync_runs').select('*').order('started_at', { ascending: false }).limit(5);
      if (data) setSyncRuns(data);
    } catch (err) {
      console.error('Erro ao carregar sync runs:', err);
    }
  }

  const categories = ['all', ...new Set(tools.map(t => t.category))];

  const filteredTools = tools.filter(t => {
    const matchSearch = !search || t.name.toLowerCase().includes(search.toLowerCase()) || t.description.toLowerCase().includes(search.toLowerCase());
    const matchCategory = filterCategory === 'all' || t.category === filterCategory;
    return matchSearch && matchCategory;
  });

  const healthCounts = {
    healthy: tools.filter(t => t.health_status === 'healthy').length,
    degraded: tools.filter(t => t.health_status === 'degraded').length,
    down: tools.filter(t => t.health_status === 'down').length,
    unknown: tools.filter(t => !t.health_status || t.health_status === 'unknown').length,
  };

  if (loading) {
    return <div className="p-6 text-center text-muted-foreground">Carregando catálogo...</div>;
  }

  return (
    <div className="space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h2 className="text-2xl font-bold">Catálogo de Ferramentas</h2>
          <p className="text-sm text-muted-foreground">{tools.length} ferramentas registradas</p>
        </div>
        <SyncButton onSyncComplete={() => { loadTools(); loadSyncRuns(); }} />
      </div>

      {/* Indicadores de saúde */}
      <div className="flex gap-4 flex-wrap">
        <Badge variant="default" className="bg-green-500/10 text-green-500 border-green-500/30">
          {healthCounts.healthy} saudáveis
        </Badge>
        <Badge variant="default" className="bg-yellow-500/10 text-yellow-500 border-yellow-500/30">
          {healthCounts.degraded} degradados
        </Badge>
        <Badge variant="default" className="bg-red-500/10 text-red-500 border-red-500/30">
          {healthCounts.down} offline
        </Badge>
        <Badge variant="outline">{healthCounts.unknown} desconhecidos</Badge>
      </div>

      {/* Filtros */}
      <div className="flex gap-4 items-center">
        <div className="relative flex-1 max-w-sm">
          <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar ferramentas..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-10"
          />
        </div>
        <div className="flex gap-2 items-center">
          <Filter className="h-4 w-4 text-muted-foreground" />
          {categories.map(cat => (
            <button
              key={cat}
              onClick={() => setFilterCategory(cat)}
              className={`px-3 py-1 rounded-full text-sm ${
                filterCategory === cat
                  ? 'bg-primary text-primary-foreground'
                  : 'bg-muted text-muted-foreground hover:bg-muted/80'
              }`}
            >
              {cat === 'all' ? 'Todas' : cat}
            </button>
          ))}
        </div>
      </div>

      {/* Grid de ferramentas */}
      <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-4">
        {filteredTools.map(tool => (
          <ToolCard key={tool.id} tool={tool} />
        ))}
      </div>

      {filteredTools.length === 0 && (
        <div className="text-center py-12 text-muted-foreground">
          Nenhuma ferramenta encontrada com os filtros atuais.
        </div>
      )}

      {/* Últimos syncs */}
      {syncRuns.length > 0 && (
        <div className="mt-8">
          <h3 className="text-lg font-semibold mb-2">Últimas sincronizações</h3>
          <div className="space-y-2">
            {syncRuns.map(run => (
              <div key={run.id} className="flex items-center justify-between text-sm bg-muted/50 rounded-lg p-3">
                <span className={run.status === 'completed' ? 'text-green-500' : run.status === 'running' ? 'text-yellow-500' : 'text-red-500'}>
                  {run.status}
                </span>
                <span>{new Date(run.started_at).toLocaleString()}</span>
                <span>{run.tools_found} encontradas, {run.tools_added} adicionadas, {run.tools_updated} atualizadas</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  );
}

import React from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Badge } from '@/shared/ui/badge';
import { Button } from '@/shared/ui/button';
import { Activity, AlertTriangle, CheckCircle2, XCircle } from 'lucide-react';

interface ToolCardProps {
  tool: {
    id: string;
    name: string;
    description: string;
    category: string;
    tags: string[];
    version: string;
    is_deprecated: boolean;
    health_status?: 'healthy' | 'degraded' | 'down' | 'unknown';
  };
  onSelect?: (id: string) => void;
}

export function ToolCard({ tool, onSelect }: ToolCardProps) {
  const healthIcon = {
    healthy: <CheckCircle2 className="h-4 w-4 text-green-500" />,
    degraded: <AlertTriangle className="h-4 w-4 text-yellow-500" />,
    down: <XCircle className="h-4 w-4 text-red-500" />,
    unknown: <Activity className="h-4 w-4 text-gray-400" />,
  };

  const healthColor = {
    healthy: 'bg-green-100 text-green-800 dark:bg-green-900 dark:text-green-200',
    degraded: 'bg-yellow-100 text-yellow-800 dark:bg-yellow-900 dark:text-yellow-200',
    down: 'bg-red-100 text-red-800 dark:bg-red-900 dark:text-red-200',
    unknown: 'bg-gray-100 text-gray-800 dark:bg-gray-900 dark:text-gray-200',
  };

  return (
    <Card
      className={`cursor-pointer transition-all hover:shadow-md ${tool.is_deprecated ? 'opacity-60' : ''}`}
      onClick={() => onSelect?.(tool.id)}
    >
      <CardHeader className="pb-2">
        <div className="flex items-center justify-between">
          <CardTitle className="text-lg font-semibold">{tool.name}</CardTitle>
          {tool.health_status && (
            <div className={`flex items-center gap-1 rounded-full px-2 py-0.5 text-xs ${healthColor[tool.health_status]}`}>
              {healthIcon[tool.health_status]}
              <span>{tool.health_status}</span>
            </div>
          )}
        </div>
        <p className="text-sm text-muted-foreground">{tool.description}</p>
      </CardHeader>
      <CardContent>
        <div className="flex flex-wrap gap-1.5">
          <Badge variant="secondary">{tool.category}</Badge>
          {tool.tags.slice(0, 3).map((tag) => (
            <Badge key={tag} variant="outline" className="text-xs">
              {tag}
            </Badge>
          ))}
          {tool.tags.length > 3 && (
            <Badge variant="outline" className="text-xs">
              +{tool.tags.length - 3}
            </Badge>
          )}
          <span className="ml-auto text-xs text-muted-foreground">v{tool.version}</span>
        </div>
        {tool.is_deprecated && (
          <div className="mt-2 flex items-center gap-1 text-xs text-red-500">
