}

import React, { useState } from 'react';
import { Button } from '@/shared/ui/button';
import { RefreshCw, CheckCircle2, XCircle, Loader2 } from 'lucide-react';
import { useToast } from '@/shared/hooks/useToast';
import { mcpClient } from '@/services/mcp-client';

interface SyncResult {
  status: string;
  tools_found: number;
  tools_added: number;
  tools_updated: number;
  errors?: string[];
}

export function SyncButton() {
  const [syncing, setSyncing] = useState(false);
  const [result, setResult] = useState<SyncResult | null>(null);
  const { toast } = useToast();

  const handleSync = async () => {
    setSyncing(true);
    setResult(null);
    try {
      const res = await mcpClient.syncCatalog();
      setResult(res);
      toast({
        title: 'Sincronização concluída',
        description: `${res.tools_added} adicionados, ${res.tools_updated} atualizados`,
        variant: res.status === 'completed' ? 'default' : 'destructive',
      });
    } catch (err) {
      toast({ title: 'Erro na sincronização', description: String(err), variant: 'destructive' });
    } finally {
      setSyncing(false);
    }
  };

  return (
    <div className="flex items-center gap-2">
      <Button onClick={handleSync} disabled={syncing} variant="outline" size="sm">
        {syncing ? <Loader2 className="h-4 w-4 animate-spin mr-1" /> : <RefreshCw className="h-4 w-4 mr-1" />}
        {syncing ? 'Sincronizando...' : 'Sincronizar Catálogo'}
      </Button>
      {result && (
        <span className="text-xs text-muted-foreground">
          {result.status === 'completed' ? (
            <span className="flex items-center gap-1 text-green-500">
              <CheckCircle2 className="h-3 w-3" /> OK
            </span>
          ) : (
            <span className="flex items-center gap-1 text-red-500">
              <XCircle className="h-3 w-3" /> Falha
            </span>
          )}
        </span>
      )}
    </div>
  );
}

import React, { useState } from 'react';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Input } from '@/shared/ui/input';
import { Label } from '@/shared/ui/label';
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from '@/shared/ui/select';
import { Textarea } from '@/shared/ui/textarea';
import { usePolicies } from '@/hooks/usePolicies';
import { RuleBadge } from './RuleBadge';
import { Shield, Plus, Save, X } from 'lucide-react';

interface PolicyForm {
  name: string;
  description: string;
  rule_type: 'allow' | 'block' | 'require_veto';
  target_tool_id: string;
  target_server_id: string;
  enabled: boolean;
}

const emptyForm: PolicyForm = {
  name: '',
  description: '',
  rule_type: 'allow',
  target_tool_id: '',
  target_server_id: '',
  enabled: true,
};

export function PolicyEditor() {
  const { policies, addPolicy, updatePolicy, loading } = usePolicies();
  const [isOpen, setIsOpen] = useState(false);
  const [form, setForm] = useState<PolicyForm>(emptyForm);
  const [editingId, setEditingId] = useState<string | null>(null);

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (editingId) {
      await updatePolicy(editingId, form);
    } else {
      await addPolicy(form);
    }
    setForm(emptyForm);
    setEditingId(null);
    setIsOpen(false);
  };

  const handleEdit = (policy: any) => {
    setForm({
      name: policy.name,
      description: policy.description || '',
      rule_type: policy.rule_type,
      target_tool_id: policy.target_tool_id || '',
      target_server_id: policy.target_server_id || '',
      enabled: policy.enabled,
    });
    setEditingId(policy.id);
    setIsOpen(true);
  };

  if (loading) {
    return <div className="p-4 text-center text-muted-foreground">Carregando editor de políticas...</div>;
  }

  return (
    <div className="space-y-4">
      <div className="flex items-center justify-between">
        <h3 className="text-lg font-semibold flex items-center gap-2">
          <Shield className="h-5 w-5" />
          Políticas de Segurança
        </h3>
        <Button onClick={() => { setForm(emptyForm); setEditingId(null); setIsOpen(!isOpen); }} variant={isOpen ? 'outline' : 'default'} size="sm">
          {isOpen ? <X className="h-4 w-4 mr-1" /> : <Plus className="h-4 w-4 mr-1" />}
          {isOpen ? 'Cancelar' : 'Nova Política'}
        </Button>
      </div>

      {isOpen && (
        <Card>
          <CardContent className="pt-4">
            <form onSubmit={handleSubmit} className="space-y-3">
              <div>
                <Label htmlFor="name">Nome</Label>
                <Input id="name" value={form.name} onChange={e => setForm({ ...form, name: e.target.value })} required />
              </div>
              <div>
                <Label htmlFor="description">Descrição</Label>
                <Textarea id="description" value={form.description} onChange={e => setForm({ ...form, description: e.target.value })} />
              </div>
              <div>
                <Label htmlFor="rule_type">Tipo de Regra</Label>
                <Select value={form.rule_type} onValueChange={v => setForm({ ...form, rule_type: v as any })}>
                  <SelectTrigger><SelectValue /></SelectTrigger>
                  <SelectContent>
                    <SelectItem value="allow">Allow</SelectItem>
                    <SelectItem value="block">Block</SelectItem>
                    <SelectItem value="require_veto">Require Veto</SelectItem>
                  </SelectContent>
                </Select>
              </div>
              <div>
                <Label htmlFor="target_tool_id">Tool ID (opcional)</Label>
                <Input id="target_tool_id" value={form.target_tool_id} onChange={e => setForm({ ...form, target_tool_id: e.target.value })} />
              </div>
              <div>
                <Label htmlFor="target_server_id">Server ID (opcional)</Label>
                <Input id="target_server_id" value={form.target_server_id} onChange={e => setForm({ ...form, target_server_id: e.target.value })} />
              </div>
              <div className="flex items-center gap-2">
                <input type="checkbox" id="enabled" checked={form.enabled} onChange={e => setForm({ ...form, enabled: e.target.checked })} />
                <Label htmlFor="enabled">Ativa</Label>
              </div>
              <Button type="submit" className="w-full">
                <Save className="h-4 w-4 mr-1" />
                {editingId ? 'Atualizar' : 'Criar'} Política
              </Button>
            </form>
          </CardContent>
        </Card>
      )}

      <div className="space-y-2">
        {policies.map(policy => (
          <Card key={policy.id} className="cursor-pointer hover:bg-accent/50" onClick={() => handleEdit(policy)}>
            <CardContent className="py-3 flex items-center justify-between">
              <div className="flex items-center gap-3">
                <RuleBadge type={policy.rule_type} />
                <div>
                  <p className="font-medium">{policy.name}</p>
                  {policy.description && <p className="text-sm text-muted-foreground">{policy.description}</p>}
                </div>
              </div>
              <span className={`text-xs px-2 py-1 rounded ${policy.enabled ? 'bg-green-100 text-green-800' : 'bg-gray-100 text-gray-500'}`}>
                {policy.enabled ? 'Ativa' : 'Inativa'}
              </span>
            </CardContent>
          </Card>
        ))}
        {policies.length === 0 && (
          <p className="text-center text-muted-foreground py-8">Nenhuma política cadastrada.</p>
        )}
      </div>
    </div>
  );
}

import React from 'react';
import { Badge } from '@/shared/ui/badge';
import { Shield, ShieldCheck, ShieldX, AlertTriangle } from 'lucide-react';

interface RuleBadgeProps {
  ruleType: 'allow' | 'block' | 'require_veto';
  enabled: boolean;
}

export function RuleBadge({ ruleType, enabled }: RuleBadgeProps) {
  if (!enabled) {
    return (
      <Badge variant="outline" className="text-muted-foreground">
        <Shield className="w-3 h-3 mr-1" />
        Desativada
      </Badge>
    );
  }

  const config = {
    allow: { icon: ShieldCheck, label: 'Permitir', variant: 'success' as const },
    block: { icon: ShieldX, label: 'Bloquear', variant: 'destructive' as const },
    require_veto: { icon: AlertTriangle, label: 'Requer Veto', variant: 'warning' as const },
  };

  const { icon: Icon, label, variant } = config[ruleType];

  return (
    <Badge variant={variant}>
      <Icon className="w-3 h-3 mr-1" />
      {label}
    </Badge>
  );
}

import React, { useState } from 'react';
import { usePolicies } from '@/hooks/usePolicies';
import { PolicyEditor } from './PolicyEditor';
import { RuleBadge } from './RuleBadge';
import { Card, CardContent, CardHeader, CardTitle } from '@/shared/ui/card';
import { Button } from '@/shared/ui/button';
import { Badge } from '@/shared/ui/badge';
import { Shield, Plus, Search, Filter } from 'lucide-react';
import { Input } from '@/shared/ui/input';
import { useAuth } from '@/hooks/useAuth';

interface Policy {
  id: string;
  name: string;
  description: string;
  rule_type: 'allow' | 'block' | 'require_veto';
  target_tool_id?: string;
  target_server_id?: string;
  enabled: boolean;
  created_by: string;
  created_at: string;
  updated_at: string;
}

export function PoliciesTab() {
  const { policies, loading, error, refresh } = usePolicies();
  const { user, isAdmin } = useAuth();
  const [search, setSearch] = useState('');
  const [filterType, setFilterType] = useState<string>('all');
  const [showEditor, setShowEditor] = useState(false);
  const [editingPolicy, setEditingPolicy] = useState<Policy | null>(null);

  const filteredPolicies = policies.filter(p => {
    const matchesSearch = p.name.toLowerCase().includes(search.toLowerCase()) ||
      p.description.toLowerCase().includes(search.toLowerCase());
    const matchesType = filterType === 'all' || p.rule_type === filterType;
    return matchesSearch && matchesType;
  });

  const handleEdit = (policy: Policy) => {
    setEditingPolicy(policy);
    setShowEditor(true);
  };

  const handleCreate = () => {
    setEditingPolicy(null);
    setShowEditor(true);
  };

  const handleEditorClose = () => {
    setShowEditor(false);
    setEditingPolicy(null);
    refresh();
  };

  if (loading) {
    return <div className="p-6 text-center text-muted-foreground">Carregando políticas...</div>;
  }

  if (error) {
    return (
      <div className="p-6 text-center">
        <p className="text-destructive mb-2">Erro ao carregar políticas</p>
        <p className="text-sm text-muted-foreground">{error}</p>
        <Button variant="outline" size="sm" className="mt-2" onClick={refresh}>
          Tentar novamente
        </Button>
      </div>
    );
  }

  return (
    <div className="space-y-4 p-4">
      <div className="flex items-center justify-between">
        <div className="flex items-center gap-2">
          <Shield className="h-5 w-5 text-primary" />
          <h2 className="text-lg font-semibold">Políticas de Segurança</h2>
          <Badge variant="outline">{policies.length} regras</Badge>
        </div>
        {isAdmin && (
          <Button size="sm" onClick={handleCreate}>
            <Plus className="h-4 w-4 mr-1" /> Nova Política
          </Button>
        )}
      </div>

      <div className="flex gap-2">
        <div className="relative flex-1">
          <Search className="absolute left-2 top-2.5 h-4 w-4 text-muted-foreground" />
          <Input
            placeholder="Buscar políticas..."
            value={search}
            onChange={e => setSearch(e.target.value)}
            className="pl-8"
          />
        </div>
        <select
          className="border rounded-md px-3 py-2 text-sm bg-background"
          value={filterType}
          onChange={e => setFilterType(e.target.value)}
        >
          <option value="all">Todos os tipos</option>
          <option value="allow">Allow</option>
          <option value="block">Block</option>
          <option value="require_veto">Require Veto</option>
        </select>
      </div>

      {showEditor && (
        <PolicyEditor
          policy={editingPolicy}
          onClose={handleEditorClose}
        />
