interface MTProtoStatus {
  connected: boolean;
  phone?: string;
  dc?: number;
  lastPing?: string;
  error?: string;
}

interface TelegramMTProtoCardProps {
  onReconnect?: () => Promise<void>;
  onDisconnect?: () => Promise<void>;
}

export function TelegramMTProtoCard({ onReconnect, onDisconnect }: TelegramMTProtoCardProps) {
  const { toast } = useToast();
  const [status, setStatus] = useState<MTProtoStatus>({ connected: false });
  const [loading, setLoading] = useState(true);
  const [reconnecting, setReconnecting] = useState(false);

  const fetchStatus = useCallback(async () => {
    try {
      const res = await fetch('https://status.centralldark.com/mtproto/status');
      if (!res.ok) throw new Error('Falha ao obter status');
      const data = await res.json();
      setStatus(data);
    } catch (err: any) {
      setStatus({ connected: false, error: err.message });
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    fetchStatus();
    const interval = setInterval(fetchStatus, 30000);
    return () => clearInterval(interval);
  }, [fetchStatus]);

  const handleReconnect = async () => {
    if (!onReconnect) return;
    setReconnecting(true);
    try {
      await onReconnect();
      toast({ title: 'Reconectando ao Telegram...', variant: 'default' });
      await fetchStatus();
    } catch (err: any) {
      toast({ title: 'Erro ao reconectar', description: err.message, variant: 'destructive' });
    } finally {
      setReconnecting(false);
    }
  };

  const handleDisconnect = async () => {
    if (!onDisconnect) return;
    try {
      await onDisconnect();
      toast({ title: 'Desconectado do Telegram', variant: 'default' });
      setStatus({ connected: false });
    } catch (err: any) {
      toast({ title: 'Erro ao desconectar', description: err.message, variant: 'destructive' });
    }
  };

  if (loading) {
    return (
      <Card>
        <CardHeader>
          <CardTitle className="flex items-center gap-2">
            <Send className="h-5 w-5" />
            Telegram MTProto
          </CardTitle>
        </CardHeader>
        <CardContent>
          <div className="flex items-center gap-2 text-muted-foreground">
            <Loader2 className="h-4 w-4 animate-spin" />
            Verificando conexão...
          </div>
        </CardContent>
      </Card>
    );
  }

  return (
    <Card>
      <CardHeader>
        <CardTitle className="flex items-center gap-2">
          <Send className="h-5 w-5" />
          Telegram MTProto
          <Badge variant={status.connected ? 'default' : 'destructive'} className="ml-2">
            {status.connected ? (
              <><CheckCircle2 className="h-3 w-3 mr-1" />Conectado</>
            ) : (
              <><XCircle className="h-3 w-3 mr-1" />Desconectado</>
            )}
          </Badge>
        </CardTitle>
      </CardHeader>
      <CardContent className="space-y-3">
        {status.connected ? (
          <>
            <div className="flex items-center gap-2 text-sm">
              <Phone className="h-4 w-4 text-muted-foreground" />
              <span>{status.phone || 'Telefone não informado'}</span>
            </div>
            {status.dc && (
              <div className="flex items-center gap-2 text-sm">
                <KeyRound className="h-4 w-4 text-muted-foreground" />
                <span>DC {status.dc}</span>
              </div>
            )}
            {status.lastPing && (
              <div className="flex items-center gap-2 text-sm text-muted-foreground">
                <span>Último ping: {new Date(status.lastPing).toLocaleString()}</span>
              </div>
            )}
            <div className="flex gap-2 pt-2">
              <Button size="sm" variant="outline" onClick={handleReconnect} disabled={reconnecting}>
                {reconnecting ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
                Reconectar
              </Button>
              <Button size="sm" variant="destructive" onClick={handleDisconnect}>
                <LogOut className="h-4 w-4 mr-1" />
                Desconectar
              </Button>
            </div>
          </>
        ) : (
          <>
            <div className="flex items-center gap-2 text-sm text-destructive">
              <ShieldAlert className="h-4 w-4" />
              <span>{status.error || 'Conexão perdida com o Telegram'}</span>
            </div>
            <Button size="sm" variant="default" onClick={handleReconnect} disabled={reconnecting} className="mt-2">
              {reconnecting ? <Loader2 className="h-4 w-4 animate-spin" /> : <RefreshCw className="h-4 w-4" />}
              Tentar reconectar
            </Button>
          </>
        )}
      </CardContent>
    </Card>
  );
}

import { useState, useEffect, useRef } from 'react';

interface MCPTool {
  id: string;
  name: string;
  description: string;
  category: string;
  tags: string[];
  version: string;
  is_deprecated: boolean;
  health_status?: 'healthy' | 'degraded' | 'down';
  last_health_check?: string;
}

interface MCPSyncRun {
  id: string;
  status: string;
  started_at: string;
  finished_at: string;
  tools_found: number;
  tools_added: number;
  tools_updated: number;
}

interface UseMCPReturn {
  tools: MCPTool[];
  syncRuns: MCPSyncRun[];
  loading: boolean;
  error: string | null;
  refetch: () => void;
  syncNow: () => Promise<void>;
  isSyncing: boolean;
}

const CACHE_DURATION = 2 * 60 * 1000; // 2 minutos

let cache: { tools: MCPTool[]; syncRuns: MCPSyncRun[]; timestamp: number } | null = null;

export function useMCP(): UseMCPReturn {
  const [tools, setTools] = useState<MCPTool[]>([]);
  const [syncRuns, setSyncRuns] = useState<MCPSyncRun[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [isSyncing, setIsSyncing] = useState(false);
  const mountedRef = useRef(true);

  const fetchData = async () => {
    try {
      setLoading(true);
      setError(null);

      if (cache && Date.now() - cache.timestamp < CACHE_DURATION) {
        setTools(cache.tools);
        setSyncRuns(cache.syncRuns);
        setLoading(false);
        return;
      }

      const [toolsRes, syncRes] = await Promise.all([
        fetch('/api/hub/tools'),
        fetch('/api/hub/sync-runs?limit=10'),
      ]);

      if (!toolsRes.ok || !syncRes.ok) {
        throw new Error('Falha ao carregar dados do MCP');
      }

      const toolsData: MCPTool[] = await toolsRes.json();
      const syncData: MCPSyncRun[] = await syncRes.json();

      cache = { tools: toolsData, syncRuns: syncData, timestamp: Date.now() };

      if (mountedRef.current) {
        setTools(toolsData);
        setSyncRuns(syncData);
      }
    } catch (err) {
      if (mountedRef.current) {
        setError(err instanceof Error ? err.message : 'Erro desconhecido');
      }
    } finally {
      if (mountedRef.current) {
        setLoading(false);
      }
    }
  };

  const syncNow = async () => {
    try {
      setIsSyncing(true);
      const res = await fetch('/api/hub/sync', { method: 'POST' });
      if (!res.ok) throw new Error('Falha ao iniciar sincronização');
      cache = null;
      await fetchData();
    } catch (err) {
      setError(err instanceof Error ? err.message : 'Erro ao sincronizar');
    } finally {
      setIsSyncing(false);
    }
  };

  useEffect(() => {
    mountedRef.current = true;
    fetchData();
    return () => { mountedRef.current = false; };
  }, []);

  return { tools, syncRuns, loading, error, refetch: fetchData, syncNow, isSyncing };
}

import { useState, useEffect, useCallback } from 'react';
import { supabase } from '@/integrations/supabase/hub-client';
import type { Policy } from '@/types/policies';

const CACHE_KEY = 'hub_policies_cache';
const CACHE_TTL = 5 * 60 * 1000; // 5 minutos

interface CacheEntry {
  data: Policy[];
  timestamp: number;
}

function getCached(): Policy[] | null {
  try {
    const raw = sessionStorage.getItem(CACHE_KEY);
    if (!raw) return null;
    const entry: CacheEntry = JSON.parse(raw);
    if (Date.now() - entry.timestamp > CACHE_TTL) {
      sessionStorage.removeItem(CACHE_KEY);
      return null;
    }
    return entry.data;
  } catch {
    return null;
  }
}

function setCache(data: Policy[]) {
  try {
    const entry: CacheEntry = { data, timestamp: Date.now() };
    sessionStorage.setItem(CACHE_KEY, JSON.stringify(entry));
  } catch { /* quota excedida, ignora */ }
}

export function usePolicies() {
  const [policies, setPolicies] = useState<Policy[]>(() => getCached() || []);
  const [loading, setLoading] = useState(!getCached());
  const [error, setError] = useState<string | null>(null);

  const fetchPolicies = useCallback(async () => {
    try {
      setLoading(true);
      setError(null);
      const { data, error: err } = await supabase
        .from('policies')
        .select('*')
        .order('created_at', { ascending: false });

      if (err) throw new Error(err.message);
      const typed = (data || []) as Policy[];
      setPolicies(typed);
      setCache(typed);
    } catch (e: any) {
      setError(e.message || 'Erro ao carregar políticas');
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    if (!getCached()) fetchPolicies();
  }, [fetchPolicies]);

  return { policies, loading, error, refetch: fetchPolicies };
}

