import { useState, useEffect } from 'react';
import { hubClient as supabase } from '@/integrations/supabase/hub-client';

export type UserRole = 'admin' | 'operator' | 'viewer';

interface UserProfile {
  id: string;
  email: string;
  role: UserRole;
}

export function useAuth() {
  const [user, setUser] = useState<UserProfile | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const getSession = async () => {
      const { data: { session } } = await supabase.auth.getSession();
      if (session?.user) {
        // Busca role customizada se houver tabela de perfis, caso contrário assume viewer
        const { data: profile } = await supabase
          .from('user_profiles')
          .select('role')
          .eq('id', session.user.id)
          .single();

        setUser({
          id: session.user.id,
          email: session.user.email || '',
          role: (profile?.role as UserRole) || 'viewer',
        });
      }
      setLoading(false);
    };

    getSession();

    const { data: { subscription } } = supabase.auth.onAuthStateChange((_event, session) => {
      if (session?.user) {
        setUser({
          id: session.user.id,
          email: session.user.email || '',
          role: 'viewer', // Refresh trigger usualmente exigiria re-fetch de profile
        });
      } else {
        setUser(null);
      }
      setLoading(false);
    });

    return () => subscription.unsubscribe();
  }, []);

  const isAdmin = user?.role === 'admin';

  return { user, loading, isAdmin };
}

import React from 'react';
import { useAuth } from '@/hooks/useAuth';
import { ShieldAlert } from 'lucide-react';

interface RoleGuardProps {
  children: React.ReactNode;
  requiredRole?: 'admin' | 'operator' | 'viewer';
  fallback?: React.ReactNode;
}

export function RoleGuard({ children, requiredRole = 'admin', fallback }: RoleGuardProps) {
  const { user, loading } = useAuth();

  if (loading) return null;

  const roles = {
    admin: 3,
    operator: 2,
    viewer: 1
  };

  const userRoleLevel = roles[user?.role as keyof typeof roles] || 0;
  const requiredLevel = roles[requiredRole];

  if (userRoleLevel < requiredLevel) {
    return fallback || (
      <div className="p-8 border-2 border-dashed rounded-lg flex flex-col items-center justify-center text-muted-foreground gap-2">
        <ShieldAlert className="h-8 w-8 text-destructive" />
        <p className="font-medium">Acesso Restrito</p>
        <p className="text-sm">Você não tem permissão de {requiredRole} para visualizar este recurso.</p>
      </div>
    );
  }

  return <>{children}</>;
}

